-- Cue Tip v0.2 draft D1 schema. Not deployed or bound to Worker.
CREATE TABLE IF NOT EXISTS stations (id INTEGER PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,base_rate_paise INTEGER NOT NULL,extra_player_paise INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS players (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,station_id INTEGER NOT NULL REFERENCES stations(id),started_at INTEGER NOT NULL,ended_at INTEGER,status TEXT NOT NULL CHECK(status IN ('active','paused','completed','void')),player_count INTEGER NOT NULL CHECK(player_count>0),play_amount_paise INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_session_per_station ON sessions(station_id) WHERE status IN ('active','paused');
CREATE TABLE IF NOT EXISTS session_rate_segments (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL REFERENCES sessions(id),started_at INTEGER NOT NULL,ended_at INTEGER,player_count INTEGER NOT NULL,rate_paise_per_min INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS session_pauses (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL REFERENCES sessions(id),started_at INTEGER NOT NULL,ended_at INTEGER);
CREATE TABLE IF NOT EXISTS menu_items (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,price_paise INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS snack_orders (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL REFERENCES sessions(id),player_id INTEGER REFERENCES players(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS snack_order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES snack_orders(id),menu_item_id INTEGER NOT NULL REFERENCES menu_items(id),item_name TEXT NOT NULL,unit_price_paise INTEGER NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS matches (id INTEGER PRIMARY KEY AUTOINCREMENT,winner_player_id INTEGER NOT NULL REFERENCES players(id),loser_player_id INTEGER NOT NULL REFERENCES players(id),played_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(winner_player_id<>loser_player_id));
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL REFERENCES sessions(id),amount_paise INTEGER NOT NULL,method TEXT NOT NULL,recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
